public synchronized List<ActivityEvent> recent(int limit) {
    if (limit < 1 || limit > capacity) {
        throw new IllegalArgumentException("limit must be between 1 and " + capacity);
    }
    List<ActivityEvent> snapshot = new ArrayList<>(events);
    int start = Math.max(0, snapshot.size() - limit);
    return List.copyOf(snapshot.subList(start, snapshot.size()));
}

