public <U> Observation<U> map(Function<? super T, ? extends U> mapper) {
    if (mapper == null) {
        throw new IllegalArgumentException("Mapper cannot be null");
    }
    if (!isAvailable()) {
        return new Observation<>(status, detail, null);
    }
    T data = this.data;
    U result = mapper.apply(data);
    if (result == null) {
        throw new IllegalArgumentException("Mapper returned null");
    }
    return new Observation<>(status, detail, result);
}

private boolean isAvailable() {
    return status == Status.SUCCESS && data != null;
}

