public synchronized List<ActivityEvent> recent(int limit) {
    if (limit < 1 || limit > capacity) {
        throw new IllegalArgumentException("limit must be between 1 and the configured capacity");
    }
    List<ActivityEvent> recentEvents = new ArrayList<>(events);
    Collections.reverse(recentEvents);
    return Collections.unmodifiableList(recentEvents.subList(0, Math.min(limit, recentEvents.size())));
}

