public synchronized ActivityWindow between(long startInclusive, long endExclusive) {
    if (startInclusive > endExclusive || startInclusive < 0 || endExclusive < 0) {
        throw new IllegalArgumentException("Invalid range");
    }

    List<ActivityEvent> filteredEvents = new ArrayList<>();
    for (ActivityEvent event : events) {
        if (event.timestamp() >= startInclusive && event.timestamp() < endExclusive) {
            filteredEvents.add(event);
        }
    }

    ActivitySummary summary = new ActivitySummary(filteredEvents);
    return new ActivityWindow(filteredEvents, summary);
}

